INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63290028', 63290028, 'analyze_legacy', 'Kab. Bandung', 'kabkota', 'DINAS PERHUBUNGAN', 'Cermin Tikung (Musrenbang) dan Cermin Tikung (Pokir)', 'Pekerjaan Konstruksi', 'E-Purchasing', 'Jawa Barat, Bandung (Kab.)', 219132500, 'May 2026', 'APBD', 1, 1, '37 Buah', 'Pengadaan dan Pemasangan Cermin Tikung untuk Program Musrenbang sebanyak 32 buah dan Pengadaan dan Pemasangan Cermin Tikung untuk Program Pokir sebanyak 5 buah', 'b. Spesifikasi Teknis 1) Ukuran Dan Bahan Cermin Tikungan 1. Pembuatan cermin tikungan dapat menggunakan cermin cembung dari bahan acrylic / polycarbonate; 2. Tebal dan diameter cermin sebagaimana tersebut diatas adalah masing-masing sebesar 3 milimeter dan tidak kurang dari 90 cm; 3. Cermin tikungan dilengkapi dengan bingkai dan topi cermin; 4. Tiang penyangga dibuat dari besi galvanis dengan ukuran diameter 2,5 inchi; 5. Tinggi cermin tikungan 3 meter disesuaikan dengan hasil manajemen dan rekayasa lalu lintas; 6. Pada bagian depan bawah cermin tikung dibubuhi Stiker logo Dinas Perhubungan dan bertuliskan Dishub Kab. Bandung; 7. Setiap bahan Cermin Tikungan yang akan dipergunakan harus lulus uji laboratorium dengan menunjukkan sertifikat uji Laboratorium berskala Nasional atau Internasional. 2) Tiang Rambu 1. Bahan Tiang Cermin Tikungan logam dengan syarat : a. Berbentuk pipa bulat, b. Bersifat anti karat, c. Tiang di cat besi warna Orange menyala. 2. Jenis konstruksi tiang Cermin Tikungan dengan bahan logam terdiri dari : a. Jenis dan Ukuran :Pipa Galvanis diameter 2,5”, dengan tebal 2 mm, b. Pipa bulat dapat diisi cor beton praktis 1:2:3 (sesuai standard konstruksi Indonesia) dan pipa tiang ditutup dengan plat besi atau bahan sejenis, sehingga air tidak dapat masuk ke dalam pipa; c. Angkur bawah terdiri dari 2 batang besi siku 3x30x30 mm yang dilas pada tiang rambu. d. Ketinggian tiang, bentuk dan ukuran tiang sebagaimana gambar terlampir. 3) Pondasi Tiang Rambu Dan Pemasangan Cermin Tikungan Pembuatan pondasi dan perletakan Tiang Cermin Tikungan. 1. Ukuran dimensi tiang rambu tunggal : - Sisi bagian atas : 400 mm - Sisi bagian bawah : 400 mm - Tinggi Pondasi : 600 mm 2. Bagian tiang yang terbenam pada pondasi sedalam 500 mm; 3. Bagian dasar galian pondasi diberi lapisan pasir yang dipadatkan dengan ketebalan 100 mm; 4. Pondasi dari beton dengan campuran semen, pasir dan batu kerikil/split perbandingan 1:2:3; 5. Bagian pondasi diatas permukaan tanah setinggi 100 mm tergantung daerah galian dan kebutuhan; 6. Tiang cermin tikungan harus dipasang pada posisi tegak lurus, ketinggian disesuaikan dengan kebutuhan di lokasi; Pemasangan tiang cermin tikungan merupakan pekerjaan yang harus dilakukan secara cermat dan teliti, untuk itu perlu pemeriksaan ketinggian dan jarak sampai akurasi 10 mm (1 cm).', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 876503);
