INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('63290314', 63290314, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS PENANGGULANGAN KEBAKARAN DAN PENYELAMATAN', 'Programmer 3 Tahap 2 (Pengelolaan Aplikasi Siaga Api Web dan Pemeliharaan Jaringan serta Server )', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 70950000, 'June 2026', 'APBD', 1, 1, '1 Orang X 6 Bulan', '1. Tersedianya Keberlangsungan penggunaan teknologi informasi untuk menunjang kinerja 2. Tersedianya respon cepat untuk penanganan permasalahan teknologi informasi 3. Terkelolanya Sistem Informasi di Dinas Penanggulangan Kebakaran dan Penyelamatan; 4. Terlaksanakan Pengelolaan Teknologi Informasi yang meliputi hardware, software, server virtual machine, dan Jaringan; 5. Pengembangan Aplikasi Siaga Api Web yang dapat mendukung interkoneksitas dan interoperabilitas, mampu berintegrasi dan berkomunikasi dengan berbagai aplikasi sistem informasi lainnya; 6. Aplikasi Siaga Api Web yang telah disempurnakan, dikembangkan, dan ditambahkan fitur sesuai dengan kebutuhan pengguna; 7. Implementasi Pengembangan Aplikasi Siaga Api Web di Dinas Penanggulangan Kebakaran dan Penyelamatan mencakup : a. Training b. Maintenance c. Analisa Bugs/Error 8. Pelatihan dan assistensi ; 9. Menyiapkan FAQ; 10. Menyajikan data sesuai dengan arahan dan instruksi pimpinan; 11. Menyajikan laporan;', '1. Pendidikan minimal S1 Jurusan Sistem Informasi / Teknik Informatika / Teknologi Informasi / Ilmu Komputer atau sejenisnya; 2. Melampirkan Daftar Riwayat Hidup/Curriculum Vitae (CV); 3. Melampirkan Ijazah, Transkip Nilai; 4. Melampirkan pengalaman kerja / kontrak kerja; 5. Mampu berkomunikasi dengan baik dan bekerja di bawah tekanan; 6. Memiliki komitmen dan minat dalam bidang kebakaran, jiwa kemanusiaan, semangat pengabdian dan dedikasi tinggi; 7. Mampu bekerja secara mandiri dan dapat bekerjasama dalam kelompok; 8. Melampirkan Surat Keterangan Sehat Jasmani dan Rohani dari RSUD, RSUP, Puskesmas Kelurahan/Kecamatan (dilampirkan pada saat dinyatakan lulus dan/atau penandatanganan kontrak) ; 9. Melampirkan Surat Pernyataan tidak menuntut untuk diangkat sebagai calon PNS dan/atau PPPK, tidak menuntut apabila proses rekrutmen dibatalkan karena ketentuan dan keputusan yang ada, bersedia menerima upah sesuai dengan yang tertuang dalam Dokumen Pelaksanaan Anggaran/ DPA, (Format Terlampir); 10. Memiliki pengalaman minimal 5 (lima) tahun sebagai Programmer pada bidang pekerjaan sejenis; 11. Menguasai Ms Office, OS, Frame work (Laravel/Code igniter/oodo), PHP,Java, Database Management System (Mysql/MongoDB), Front end (HTML, CSS, JS, Bootstrap,Tailwind);', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 878780);
